// Trading Lab dashboard. Plain JS; data from data/*.json (generated by build_site.py).
const $ = (s, el = document) => el.querySelector(s);
const esc = s => String(s ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const inr = v => v == null ? "—" : (v < 0 ? "−" : "") + "₹" + Math.abs(Math.round(v)).toLocaleString("en-IN");
const cls = v => v == null ? "" : v > 0 ? "good" : v < 0 ? "bad" : "";
const link = (u, t) => u ? `<a href="${esc(u)}" target="_blank" rel="noopener">${esc(t || host(u))}</a>` : "";
const host = u => { try { return new URL(u).hostname.replace(/^www\./, ""); } catch { return "link"; } };
const D = {};
const charts = {};
function chart(id, cfg) { if (charts[id]) charts[id].destroy(); const c = document.getElementById(id); if (c && window.Chart) charts[id] = new Chart(c, cfg); }
if (window.Chart) { Chart.defaults.color = "#93a0b8"; Chart.defaults.borderColor = "#2a3550"; }

document.querySelectorAll("#tabs button").forEach(b => b.onclick = () => { location.hash = b.dataset.tab; });
function route() {
  const [tab, sub] = (location.hash.slice(1) || "overview").split("/");
  const b = document.querySelector(`#tabs button[data-tab="${tab}"]`) || document.querySelector("#tabs button");
  document.querySelectorAll("#tabs button").forEach(x => x.classList.toggle("active", x === b));
  document.querySelectorAll(".tab").forEach(t => t.classList.toggle("active", t.id === b.dataset.tab));
  if (b.dataset.tab === "bots") botDetail(sub || "");
}
window.addEventListener("hashchange", route);

async function load() {
  const names = ["meta", "backtests", "leaderboard", "paper", "news", "research", "bots"];
  await Promise.all(names.map(async n => { try { D[n] = await (await fetch(`data/${n}.json`, { cache: "no-cache" })).json(); } catch { D[n] = null; } }));
  $("#updated").textContent = D.meta ? "last updated " + D.meta.updated_ist : "data unavailable";
  [overview, strategies, gate, paper, news, research, bots].forEach(f => { try { f(); } catch (e) { console.error(f.name, e); } });
  route();
}

// ---------------------------------------------------------------- Overview
function overview() {
  const m = D.meta, bt = D.backtests, p = D.paper;
  const pt = m.planner_today;
  const fams = (bt?.families || []).filter(f => f.best_oos != null).sort((a, b) => b.best_oos - a.best_oos);
  $("#overview").innerHTML = `
  <h2>Where things stand</h2>
  <div class="grid">
    <div class="card"><div class="kpi">${m.variants.toLocaleString("en-IN")}<small>strategy variants backtested (${m.real} on real data)</small></div></div>
    <div class="card"><div class="kpi ${m.passed ? "good" : "bad"}">${m.passed}<small>passed the strict out-of-sample gate</small></div></div>
    <div class="card"><div class="kpi">${m.families}<small>strategy families tried</small></div></div>
    <div class="card"><div class="kpi">${pt ? pt.total : 0}<small>setups Trade Planner reviewed on ${pt ? pt.date : "—"} · ${pt ? Object.entries(pt.counts).map(([k, v]) => `${v} ${k}`).join(", ") : ""}</small></div></div>
    <div class="card"><div class="kpi">${p?.strangle?.journal?.length || 0}<small>rows in the strangle paper journal (exploratory)</small></div></div>
  </div>
  <div class="card" style="margin-top:12px"><ul class="clean status">${m.status.map(s => `<li>${esc(s)}</li>`).join("")}</ul></div>
  <div class="note"><b>Current suggestion:</b> ${esc(m.recommendation)}</div>
  <h3>Best unseen-months (OOS) result per family</h3>
  <p class="muted">Each bar is the best out-of-sample net ₹ of any variant in that family. Picking the best of many variants flatters results, which is why the gate also checks statistical strength.</p>
  <div class="card"><div class="chartbox" style="height:${Math.max(340, fams.length * 18)}px"><canvas id="ovChart"></canvas></div></div>`;
  chart("ovChart", { type: "bar", data: { labels: fams.map(f => f.family), datasets: [{ label: "Best OOS net ₹", data: fams.map(f => f.best_oos), backgroundColor: fams.map(f => f.best_oos >= 0 ? "#2ecc71" : "#ff5c5c") }] },
    options: { indexAxis: "y", maintainAspectRatio: false, plugins: { legend: { display: false }, tooltip: { callbacks: { label: c => inr(c.raw) } } }, scales: { x: { ticks: { callback: v => inr(v) } } } } });
}

// ---------------------------------------------------------------- Strategies
let sortKey = "oos", sortDir = -1;
function strategies() {
  const bt = D.backtests; if (!bt) return;
  const fams = [...new Set(bt.rows.map(r => r.family))].sort();
  const insts = [...new Set(bt.rows.map(r => r.instrument))].sort();
  const famCards = bt.families.slice().sort((a, b) => b.variants - a.variants).map(f => `
    <div class="card"><h4>${esc(f.family)}</h4>
    <p class="muted">${f.variants} variants · ${f.real} real · ${f.trades.toLocaleString("en-IN")} trades</p>
    <p>Best net: <b class="${cls(f.best_net)}">${inr(f.best_net)}</b> · best OOS: <b class="${cls(f.best_oos)}">${inr(f.best_oos)}</b></p>
    <p>OOS positive: ${f.oos_positive}/${f.oos_known} · gate: ${f.passed ? `<span class="pill pass">${f.passed} PASS</span>` : `<span class="pill fail">0 pass</span>`}</p>
    <p><a href="#" data-fam="${esc(f.family)}">show variants ↓</a></p></div>`).join("");
  $("#strategies").innerHTML = `
  <h2>Every strategy we tried</h2>
  <p class="muted">Every backtest variant logged by the bots in the shared log. <b>IS</b> = in-sample (data used to tune). <b>OOS</b> = out-of-sample (later months never used for tuning — the number that matters). <b>MODELED</b> rows use synthetic prices and never count as evidence.</p>
  <h3>Out-of-sample net by family (sum of all variants with an OOS figure)</h3>
  <div class="card"><div class="chartbox"><canvas id="famChart"></canvas></div></div>
  <h3>Families</h3><div class="grid wide" id="famCards">${famCards}</div>
  <h3 id="vtable">All variants</h3>
  <div class="controls">
    <input type="search" id="q" placeholder="Search strategy, variant, notes…">
    <select id="fFam"><option value="">All families</option>${fams.map(f => `<option>${esc(f)}</option>`).join("")}</select>
    <select id="fInst"><option value="">All instruments</option>${insts.map(f => `<option>${esc(f)}</option>`).join("")}</select>
    <select id="fSrc"><option value="">REAL + MODELED</option><option>REAL</option><option>MODELED</option><option>ANECDOTE</option></select>
    <select id="fOos"><option value="">Any OOS</option><option value="pos">OOS &gt; 0</option><option value="neg">OOS ≤ 0</option><option value="sel">Gated (selected) only</option></select>
  </div>
  <p class="muted" id="count"></p>
  <div class="tablewrap"><table id="bt"><thead><tr>
    ${[["family","Family"],["instrument","Instrument"],["variant","Variant"],["src","Data"],["trades","Trades"],["win","Win %"],["net","Net ₹"],["is","IS ₹"],["oos","OOS ₹"],["dd","Max DD*"],["gate","Gate"],["date","Run date"],["notes","Notes"]].map(([k,t]) => `<th data-k="${k}">${t}</th>`).join("")}
  </tr></thead><tbody></tbody></table></div>
  <p class="muted">*Max DD is shown as logged (percent of capital for most runs, ₹ for some option grids). Click headers to sort.</p>`;
  const agg = {}; bt.rows.forEach(r => { if (r.oos != null && r.src === "REAL" && !r.invalid) agg[r.family] = (agg[r.family] || 0) + r.oos; });
  const ent = Object.entries(agg).sort((a, b) => b[1] - a[1]);
  chart("famChart", { type: "bar", data: { labels: ent.map(e => e[0]), datasets: [{ data: ent.map(e => e[1]), backgroundColor: ent.map(e => e[1] >= 0 ? "#2ecc71" : "#ff5c5c") }] },
    options: { maintainAspectRatio: false, plugins: { legend: { display: false }, tooltip: { callbacks: { label: c => inr(c.raw) } } }, scales: { y: { ticks: { callback: v => inr(v) } }, x: { ticks: { autoSkip: false, maxRotation: 70, minRotation: 45, font: { size: 10 } } } } } });
  ["q", "fFam", "fInst", "fSrc", "fOos"].forEach(id => $("#" + id).addEventListener("input", drawTable));
  document.querySelectorAll("#bt th").forEach(th => th.onclick = () => { const k = th.dataset.k; sortDir = sortKey === k ? -sortDir : -1; sortKey = k; drawTable(); });
  document.querySelectorAll("#famCards a[data-fam]").forEach(a => a.onclick = e => { e.preventDefault(); $("#fFam").value = a.dataset.fam; drawTable(); $("#vtable").scrollIntoView({ behavior: "smooth" }); });
  drawTable();
}
function drawTable() {
  const q = $("#q").value.toLowerCase(), fam = $("#fFam").value, inst = $("#fInst").value, src = $("#fSrc").value, o = $("#fOos").value;
  let rows = D.backtests.rows.filter(r => (!fam || r.family === fam) && (!inst || r.instrument === inst) && (!src || r.src === src)
    && (!o || (o === "pos" ? r.oos > 0 : o === "neg" ? r.oos != null && r.oos <= 0 : r.selected))
    && (!q || (r.family + " " + r.strategy + " " + r.variant + " " + r.notes + " " + r.instrument_full).toLowerCase().includes(q)));
  rows.sort((a, b) => { const x = a[sortKey], y = b[sortKey]; if (x == null) return 1; if (y == null) return -1; return (x > y ? 1 : x < y ? -1 : 0) * sortDir; });
  $("#count").textContent = `${rows.length} of ${D.backtests.rows.length} variants`;
  $("#bt tbody").innerHTML = rows.slice(0, 1500).map(r => `<tr>
    <td>${esc(r.family)}</td><td>${esc(r.instrument)}</td><td title="${esc(r.strategy)}">${esc(r.variant)}${r.invalid ? ' <span class="pill fail">INVALID</span>' : ""}</td>
    <td>${r.src === "REAL" ? "REAL" : `<span class="pill rumor">${esc(r.src)}</span>`}</td>
    <td class="n">${r.trades ?? "—"}</td><td class="n">${r.win ?? "—"}</td><td class="n ${cls(r.net)}">${inr(r.net)}</td>
    <td class="n ${cls(r.is)}">${inr(r.is)}</td><td class="n ${cls(r.oos)}"><b>${inr(r.oos)}</b></td><td class="n">${r.dd ?? "—"}</td>
    <td><span class="pill ${r.gate === "PASS" ? "pass" : "fail"}">${r.gate}${r.selected ? " (gated)" : ""}</span></td>
    <td class="muted">${esc(r.date)}</td><td class="muted" style="min-width:260px">${esc(r.notes)}</td></tr>`).join("");
}

// ---------------------------------------------------------------- Gate & leaderboard
function gate() {
  const L = D.leaderboard; if (!L) return;
  const lb = L.leaderboard.length ? `<div class="tablewrap"><table><tr><th>Strategy</th><th>Variant</th><th>Trades</th><th>OOS ₹</th></tr>${L.leaderboard.map(r => `<tr><td>${esc(r.strategy)}</td><td>${esc(r.variant)}</td><td class="n">${r.trades}</td><td class="n">${inr(r.oos)}</td></tr>`).join("")}</table></div>`
    : `<div class="alert"><b>Leaderboard is empty.</b> No strategy has passed the out-of-sample validation gate on real data yet${L.trials ? ` (≈ ${L.trials} variants tried)` : ""}. Under Mohmmadali's rule, Trade Planner therefore blocks every setup — no paper tickets until something passes.</div>`;
  $("#gate").innerHTML = `
  <h2>Leaderboard (validated strategies only)</h2>${lb}
  <h3>The validation gate, in plain English</h3>
  <p class="muted">A strategy must pass <b>all</b> of these before it can even be paper traded. The bar is high on purpose: when you test hundreds of ideas, some look great by luck.</p>
  <div class="grid wide">${L.gate.map((g, i) => `<div class="card"><h4>${i + 1}. ${esc(g.rule)}</h4><p>${esc(g.plain)}</p></div>`).join("")}</div>
  <h3>Near-miss candidates</h3>
  <div class="grid wide">${L.near_miss.map(n => `<div class="card"><h4>${esc(n.name)}</h4><p><span class="pill fail">${esc(n.status)}</span></p>
     <ul class="clean">${n.numbers.map(x => `<li>${esc(x)}</li>`).join("")}</ul><p><b>Capital:</b> ${esc(n.capital)}</p><p class="muted">Source: ${esc(n.source)}</p></div>`).join("")}</div>
  <details><summary>Gated candidates that failed (${L.gated_candidates.length})</summary>
   <div class="tablewrap"><table><tr><th>Family</th><th>Variant</th><th>Trades</th><th>IS ₹</th><th>OOS ₹</th><th>Why it failed</th></tr>
   ${L.gated_candidates.map(r => `<tr><td>${esc(r.family)}</td><td>${esc(r.variant)}</td><td class="n">${r.trades ?? "—"}</td><td class="n ${cls(r.is)}">${inr(r.is)}</td><td class="n ${cls(r.oos)}">${inr(r.oos)}</td><td class="muted">${esc(r.notes)}</td></tr>`).join("")}</table></div></details>`;
}

// ---------------------------------------------------------------- Paper trading
function paper() {
  const P = D.paper; if (!P) return; const s = P.strangle;
  const j = s.journal;
  const pref = ["event", "logged_ist", "expiry", "entry_date", "spot", "vix_pct", "ce_strike", "pe_strike", "ce_fill", "pe_fill", "credit_pts", "settle_underlying", "net", "notes"];
  const cols = j.length ? (pref.filter(k => k in j[0]).length >= 4 ? pref.filter(k => k in j[0]) : Object.keys(j[0]).slice(0, 14)) : [];
  const margin = s.margin_checks.filter(m => /groww/i.test(m.source || ""));
  $("#paper").innerHTML = `
  <h2>Paper trading</h2>
  <div class="note">Nothing here uses real money. Every setup is blocked until it passes the gate; the only paper test running is the <b>exploratory</b> Nifty weekly strangle (it failed the strict gate, and the user chose to keep it as a free information test).</div>
  <h3>Exploratory Nifty weekly strangle</h3>
  <div class="grid">
    <div class="card"><div class="kpi ${cls(s.cum)}">${inr(s.cum)}<small>cumulative paper P&amp;L per lot (settled trades)</small></div></div>
    <div class="card"><div class="kpi">${s.curve.length}<small>settled trades · pass criteria needs ≥ 16</small></div></div>
    <div class="card"><div class="kpi warn">${inr(s.stop_entries)}<small>stop-new-entries level</small></div></div>
    <div class="card"><div class="kpi bad">${inr(s.retire)}<small>retire-strategy level</small></div></div>
  </div>
  <div class="card" style="margin-top:12px"><div class="chartbox"><canvas id="paperChart"></canvas></div>${s.curve.length ? "" : `<p class="muted">No settled trades yet. First entry: Mon 26-Oct-2026 ≈ 15:20 IST for the Tue 27-Oct expiry; settlement is recorded on the next run.</p>`}</div>
  <div class="grid wide" style="margin-top:12px">
   <div class="card"><h4>Frozen rules</h4><ul class="clean">${s.rules.map(r => `<li>${esc(r)}</li>`).join("")}</ul></div>
   <div class="card"><h4>Margin check</h4><p>${margin.length ? margin.map(m => `${esc(m.date)}: ${inr(+m.margin_per_lot_incl_elm)} (${esc(m.source)})`).join("<br>") : "Estimate ≈ ₹2.38L per lot (Zerodha public calculator). <b>Not yet confirmed on Groww.</b>"}</p></div>
  </div>
  <h3>Journal (entries, skips, settlements)</h3>
  ${j.length ? `<div class="tablewrap"><table><tr>${cols.map(c => `<th>${esc(c)}</th>`).join("")}</tr>${j.map(r => `<tr>${cols.map(c => `<td>${esc(r[c])}</td>`).join("")}</tr>`).join("")}</table></div>` : `<p class="muted">Journal not started yet (created on the first real run).</p>`}
  <h3>Trade Planner daily verdicts</h3>
  <div class="card"><div class="chartbox" style="height:260px"><canvas id="planChart"></canvas></div></div>
  <div class="tablewrap" style="margin-top:10px"><table><tr><th>Date</th><th>Reviewed</th><th>Verdicts</th><th>Block reasons</th><th>Strangle event check</th></tr>
  ${P.planner_days.slice().reverse().map(d => `<tr><td>${d.date}</td><td class="n">${d.total}</td><td>${Object.entries(d.counts).map(([k, v]) => `<span class="pill ${k === "BLOCK" ? "fail" : "pass"}">${v} ${esc(k)}</span>`).join("")}</td><td>${Object.entries(d.reasons).map(([k, v]) => `${esc(k)} (${v})`).join("; ")}</td><td class="muted">${d.strangle_event_check ? esc(`${d.strangle_event_check.done_at || ""}: ${d.strangle_event_check.reason || ""}`) : "—"}</td></tr>`).join("")}</table></div>
  <p class="muted">Paper Desk journal files: ${P.paper_desk_journal_files.length ? P.paper_desk_journal_files.map(esc).join(", ") : "none yet (no approved paper tickets)"}.</p>`;
  chart("paperChart", { type: "line", data: { labels: s.curve.length ? s.curve.map(c => c.date) : ["start"], datasets: [
      { label: "Cumulative paper P&L", data: s.curve.length ? s.curve.map(c => c.cum) : [0], borderColor: "#4ea1ff", tension: .2 },
      { label: "Stop entries (−₹57k)", data: (s.curve.length ? s.curve : [0]).map(() => s.stop_entries), borderColor: "#f5a623", borderDash: [6, 4], pointRadius: 0 },
      { label: "Retire (−₹75k)", data: (s.curve.length ? s.curve : [0]).map(() => s.retire), borderColor: "#ff5c5c", borderDash: [6, 4], pointRadius: 0 }] },
    options: { maintainAspectRatio: false, scales: { y: { ticks: { callback: v => inr(v) } } } } });
  const kinds = [...new Set(P.planner_days.flatMap(d => Object.keys(d.counts)))];
  chart("planChart", { type: "bar", data: { labels: P.planner_days.map(d => d.date), datasets: kinds.map(k => ({ label: k, data: P.planner_days.map(d => d.counts[k] || 0), backgroundColor: k === "BLOCK" ? "#ff5c5c" : "#2ecc71" })) },
    options: { maintainAspectRatio: false, scales: { x: { stacked: true }, y: { stacked: true } } } });
}

// ---------------------------------------------------------------- News
function news() {
  const N = D.news; if (!N) return;
  const dates = Object.keys(N.days).sort().reverse();
  const types = [...new Set(N.events.map(e => e.type))].sort();
  const today = new Date(Date.now() + 5.5 * 3600e3).toISOString().slice(0, 10);
  $("#news").innerHTML = `
  <h2>Market news &amp; calendar</h2>
  <p class="muted">Logged by Market News Desk with a source on every line. Labels: <span class="pill fact">fact (official source)</span> exchange/regulator documents · <span class="pill media">media (headline)</span> · <span class="pill rumor">report / opinion</span> media reports, analyst views, unverified items. Fact/rumour labels and impact are derived automatically from the log wording and sources — open the link before relying on anything.</p>
  <h3>FII / DII flows</h3><div id="flows"></div>
  <h3>Daily news log</h3>
  <div class="controls"><select id="nDate">${dates.map(d => `<option>${d}</option>`).join("")}</select>
   <select id="nTag"><option value="">All tags</option></select>
   <select id="nKind"><option value="">Fact + media + reports</option><option>fact (official source)</option><option>media (headline)</option><option>report / opinion</option></select>
   <input type="search" id="nQ" placeholder="Search headline or ticker…"></div>
  <div id="nList"></div>
  <h3>Events calendar</h3>
  <div class="controls"><select id="eType"><option value="">All types</option>${types.map(t => `<option>${esc(t)}</option>`).join("")}</select>
   <select id="eVer"><option value="">Verified + unverified</option><option value="1">Verified only</option><option value="0">Unverified only</option></select>
   <select id="eWhen"><option value="up">Upcoming</option><option value="">All (incl. past)</option></select>
   <input type="search" id="eQ" placeholder="Search events or symbols…"></div>
  <div class="tablewrap"><table id="evt"><thead><tr><th>Date</th><th>Time IST</th><th>Type</th><th>Event</th><th>Symbols</th><th>Impact</th><th>Verified</th><th>Source</th></tr></thead><tbody></tbody></table></div>`;
  const fl = N.flows;
  $("#flows").innerHTML = fl.length ? `<div class="grid">${fl.slice(-5).reverse().map(f => `<div class="card"><h4>${f.date}</h4><p>FII net: <b class="${cls(f.fii_net_cr)}">${f.fii_net_cr != null ? (f.fii_net_cr > 0 ? "+" : "") + "₹" + f.fii_net_cr.toLocaleString("en-IN") + " cr" : "—"}</b></p><p>DII net: <b class="${cls(f.dii_net_cr)}">${f.dii_net_cr != null ? (f.dii_net_cr > 0 ? "+" : "") + "₹" + f.dii_net_cr.toLocaleString("en-IN") + " cr" : "—"}</b></p><p class="muted">NSE provisional</p></div>`).join("")}</div>`
    : (N.flow_lines.length ? N.flow_lines.map(l => `<p>${esc(l.text)} ${l.urls.map(u => link(u)).join(" ")}</p>`).join("") : `<p class="muted">No flows logged.</p>`);
  const drawNews = () => {
    const d = $("#nDate").value, runs = N.days[d] || [];
    const tags = [...new Set(runs.flatMap(r => r.items.map(i => i.tag)))].sort();
    const cur = $("#nTag").value; $("#nTag").innerHTML = `<option value="">All tags</option>` + tags.map(t => `<option ${t === cur ? "selected" : ""}>${t}</option>`).join("");
    const tag = $("#nTag").value, kind = $("#nKind").value, q = $("#nQ").value.toLowerCase();
    $("#nList").innerHTML = runs.slice().reverse().map(r => {
      const items = r.items.filter(i => (!tag || i.tag === tag) && (!kind || i.kind === kind) && (!q || (i.text + " " + i.tickers.join(" ")).toLowerCase().includes(q)));
      return `<details open><summary>${esc(r.time)} IST · ${esc(r.slot)} · ${esc(r.author)} <span class="muted">(${items.length} items${r.routed.length ? ", routed: " + r.routed.map(x => esc(x.to + " " + x.symbols.join(","))).join("; ") : r.routed_note ? ", nothing routed" : ""})</span></summary>
        ${r.summary ? `<p class="muted">${esc(r.summary)}</p>` : ""}
        ${items.map(i => `<div class="item"><span class="pill">${esc(i.tag)}</span><span class="pill ${i.impact}">${i.impact}</span><span class="pill ${i.kind.startsWith("fact") ? "fact" : i.kind.startsWith("media") ? "media" : "rumor"}">${esc(i.kind)}</span>${i.tickers.map(t => `<span class="pill">${esc(t)}</span>`).join("")}${i.routed_to ? `<span class="pill pass">→ ${esc(i.routed_to)}</span>` : ""}
          <div>${esc(i.text)}</div><div class="muted">${i.urls.map(u => link(u)).join(" · ")}</div></div>`).join("") || `<p class="muted">No matching items.</p>`}</details>`;
    }).join("") || `<p class="muted">No log for this date.</p>`;
  };
  const drawEv = () => {
    const t = $("#eType").value, v = $("#eVer").value, w = $("#eWhen").value, q = $("#eQ").value.toLowerCase();
    const ev = N.events.filter(e => (!t || e.type === t) && (v === "" || String(+!!e.verified) === v) && (!w || e.date >= today) && (!q || (e.title + " " + (e.symbols || []).join(" ")).toLowerCase().includes(q)));
    $("#evt tbody").innerHTML = ev.map(e => `<tr><td style="white-space:nowrap">${esc(e.date)}</td><td>${esc(e.time_ist || "")}</td><td><span class="pill">${esc(e.type)}</span></td><td>${esc(e.title)}${e.notes ? `<div class="muted">${esc(e.notes)}</div>` : ""}</td><td>${(e.symbols || []).map(esc).join(", ")}</td><td><span class="pill ${esc(e.impact)}">${esc(e.impact)}</span></td><td>${e.verified ? '<span class="pill fact">verified</span>' : '<span class="pill rumor">unverified</span>'}</td><td>${link(e.source_url)}</td></tr>`).join("") || `<tr><td colspan="8" class="muted">No events match.</td></tr>`;
  };
  ["nDate", "nTag", "nKind", "nQ"].forEach(id => $("#" + id).addEventListener("input", drawNews));
  ["eType", "eVer", "eWhen", "eQ"].forEach(id => $("#" + id).addEventListener("input", drawEv));
  drawNews(); drawEv();
}

// ---------------------------------------------------------------- Research
function research() {
  const R = D.research; if (!R) return;
  $("#research").innerHTML = `
  <h2>Research pipeline</h2>
  <div class="card"><h4>Where research is heading</h4><ul class="clean">${R.next_focus.map(x => `<li>${esc(x)}</li>`).join("")}</ul>${R.trials ? `<p class="muted">≈ ${R.trials} variants tried so far; every new trial raises the bar for statistical significance.</p>` : ""}</div>
  <h3>Rule ideas (rules.md)</h3>
  <div class="tablewrap"><table><tr><th>Rule</th><th>Status</th><th>Idea / verdict</th></tr>${R.queue.map(q => `<tr><td><b>${esc(q.title)}</b></td><td><span class="pill ${/REJECT|none passed/.test(q.status) ? "fail" : /PASS/.test(q.status) ? "pass" : "medium"}">${esc(q.status)}</span></td><td class="muted">${esc(q.detail)}</td></tr>`).join("")}</table></div>
  ${R.week_ahead.length ? `<h3>Week ahead (from the latest research digest)</h3><div class="tablewrap"><table><tr><th>Date</th><th>Event</th></tr>${R.week_ahead.map(w => `<tr><td style="white-space:nowrap">${esc(w.date)}</td><td>${esc(w.event)}</td></tr>`).join("")}</table></div>` : ""}
  <h3>Weekly improvement cycles</h3>
  ${R.weekly.map(w => `<div class="card" style="margin-bottom:8px"><h4>${esc(w.title)}</h4><ul class="clean">${w.headline.map(h => `<li>${esc(h)}</li>`).join("")}</ul></div>`).join("") || `<p class="muted">None yet.</p>`}
  <h3>Backtest runs (newest first)</h3>
  <div class="tablewrap" style="max-height:420px"><table><tr><th>Date</th><th>Bot</th><th>Variants</th><th>Passed</th><th>Families</th></tr>${R.runs.map(r => `<tr><td style="white-space:nowrap">${esc(r.date)}</td><td>${esc(r.bot)}</td><td class="n">${r.rows}</td><td class="n">${r.passed}</td><td class="muted">${r.families.map(esc).join(", ")}</td></tr>`).join("")}</table></div>
  <h3>Reports</h3><ul class="clean">${R.reports.map(r => `<li>${esc(r.title)} <span class="muted">(${esc(r.file)})</span></li>`).join("")}</ul>`;
}

// ---------------------------------------------------------------- Bots
const slug = s => String(s).toLowerCase().replace(/\(.*?\)/g, "").trim().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
const runBots = { "grok-bot": ["trading-coordinator", "groww-bot (research executor)", "groww-bot"], "trading-research-bot": ["trading-research"], "trade-planner": ["india-day-trader"] };
function bots() {
  const B = D.bots; if (!B) return;
  $("#bots").innerHTML = `<div id="botList"></div><div id="botDetail" hidden></div>`;
  $("#botList").innerHTML = `
  <h2>The bot team</h2>
  <div class="alert"><b>House rules:</b><ul class="clean">${B.rules.map(r => `<li>${esc(r)}</li>`).join("")}</ul></div>
  <h3>How information flows</h3>
  <div class="mermaid" id="flow">
flowchart TD
  N[Market News Desk<br/>news + events calendar] -->|events.json, routed items| S[Market Scout<br/>setups + ORB hits]
  N -->|event vetoes| P[Trade Planner<br/>plan or BLOCK]
  S -->|watchlist / hits| P
  L[(Shared backtest log<br/>leaderboard)] -->|only validated setups pass| P
  P -->|PASS tickets / BLOCK counts| G{{Grok Bot<br/>coordinator}}
  G -->|user's yes/no| D[Paper Desk<br/>paper fills + journal]
  D -->|weekly paper results| L
  R[Trading research bot<br/>rules, grids, strangle paper test] -->|backtest rows| L
  G -->|weekly improvement cycle| L
  P -->|strangle event-veto note| R
  N --> R
  G <-->|questions, decisions| U((Mohmmadali))
  O[Opportunity Hunter<br/>side-income research] -->|weekly top-3| G
  G -->|rebuild| W[This website]
  </div>
  <h3>Bots <span class="muted" style="font-size:.85rem">— click a bot for its detail page</span></h3>
  <div class="grid wide">${B.bots.map(b => `<a class="card botcard" href="#bots/${slug(b.name)}"><h4>${b.emoji} ${esc(b.name)}</h4><p>${esc(b.role)}</p>
    <p><b>Schedule (IST):</b> ${b.schedule.map(esc).join(" · ")}</p>
    <div class="note" style="margin:8px 0 0"><b>Latest:</b> ${esc(b.latest)}</div><p class="more">Open details →</p></a>`).join("")}</div>`;
}
function botDetail(s) {
  const B = D.bots; if (!B) return;
  const b = B.bots.find(x => slug(x.name) === s);
  const list = $("#botList"), det = $("#botDetail");
  if (!b) { list.hidden = false; det.hidden = true; renderMermaid(); return; }
  list.hidden = true; det.hidden = false;
  const others = B.bots.filter(x => x !== b).map(x => `<a class="pill" href="#bots/${slug(x.name)}">${x.emoji} ${esc(x.name)}</a>`).join("");
  let extra = "";
  const R = D.research, P = D.paper, N = D.news;
  const runsTable = names => { const rs = (R?.runs || []).filter(r => names.includes(r.bot)); return rs.length ? `<h3>Backtest runs (${rs.length})</h3><div class="tablewrap" style="max-height:420px"><table><tr><th>Date</th><th>Variants</th><th>Passed</th><th>Families</th></tr>${rs.map(r => `<tr><td style="white-space:nowrap">${esc(r.date)}</td><td class="n">${r.rows}</td><td class="n">${r.passed}</td><td class="muted">${r.families.map(esc).join(", ")}</td></tr>`).join("")}</table></div>` : `<p class="muted">No backtest runs logged.</p>`; };
  if (s === "market-scout") {
    const sc = B.scout;
    extra = `<h3>Hits — ${esc(sc.date || "none")} (${sc.hits.length})</h3>
    <div class="grid"><div class="card"><h4>By scan</h4>${Object.entries(sc.by_scan).map(([k, v]) => `<p>${esc(k)}: <b>${v}</b></p>`).join("") || "<p class='muted'>none</p>"}</div>
     <div class="card"><div class="chartbox" style="height:220px"><canvas id="setupChart"></canvas></div></div></div>
    <div class="controls"><input type="search" id="hQ" placeholder="Filter hits by symbol / setup…"></div>
    <div class="tablewrap" style="max-height:480px"><table id="hits"><thead><tr><th>Time</th><th>Scan</th><th>Symbol</th><th>Setup</th><th>Price</th><th>% over level</th><th>News</th></tr></thead><tbody></tbody></table></div>
    <p class="muted">Hits are scan alerts, not trades. Trade Planner blocks every one until a strategy passes the gate.</p>`;
  } else if (s === "trade-planner") {
    const pd = P?.planner_days || [];
    extra = `<h3>Daily verdicts</h3><div class="tablewrap"><table><tr><th>Date</th><th>Reviewed</th><th>Verdicts</th><th>Block reasons</th><th>Strangle event check</th></tr>
    ${pd.slice().reverse().map(d => `<tr><td>${d.date}</td><td class="n">${d.total}</td><td>${Object.entries(d.counts).map(([k, v]) => `<span class="pill ${k === "BLOCK" ? "fail" : "pass"}">${v} ${esc(k)}</span>`).join("")}</td><td>${Object.entries(d.reasons).map(([k, v]) => `${esc(k)} (${v})`).join("; ")}</td><td class="muted">${d.strangle_event_check ? esc(`${d.strangle_event_check.done_at || ""}: ${d.strangle_event_check.reason || ""}`) : "—"}</td></tr>`).join("") || `<tr><td colspan="5" class="muted">No planner log yet.</td></tr>`}</table></div>
    <h3>The gate it enforces</h3><ul class="clean">${(D.leaderboard?.gate || []).map(g => `<li>${esc(typeof g === "string" ? g : (g.rule || g.name || "") + (g.plain ? ": " + g.plain : g.text ? ": " + g.text : ""))}</li>`).join("")}</ul>`;
  } else if (s === "paper-desk") {
    const j = P?.strangle?.journal || [];
    extra = `<h3>Paper journals</h3><p>Paper Desk journal files: ${P?.paper_desk_journal_files?.length ? P.paper_desk_journal_files.map(esc).join(", ") : "none yet: no ticket has been approved, because nothing has passed the gate."}</p>
    <p>Exploratory strangle journal (run by Trading research bot): <b>${j.length}</b> rows, cumulative ${inr(P?.strangle?.cum)}. <a href="#paper">See Paper trading →</a></p>`;
  } else if (s === "market-news-desk") {
    const dates = Object.keys(N?.days || {}).sort().reverse();
    extra = `<h3>Runs logged</h3>${dates.map(d => `<details ${d === dates[0] ? "open" : ""}><summary>${d} · ${N.days[d].length} runs · ${N.days[d].reduce((a, r) => a + r.items.length, 0)} items</summary><div class="tablewrap"><table><tr><th>Time IST</th><th>Slot</th><th>Items</th><th>Routed</th></tr>${N.days[d].map(r => `<tr><td>${esc(r.time)}</td><td>${esc(r.slot)}</td><td class="n">${r.items.length}</td><td>${r.routed.length ? r.routed.map(x => esc(x.to + " " + x.symbols.join(","))).join("; ") : "—"}</td></tr>`).join("")}</table></div></details>`).join("") || "<p class='muted'>No logs.</p>"}
    <p>Events calendar: <b>${N?.events?.length || 0}</b> events (${(N?.events || []).filter(e => e.verified).length} verified). <a href="#news">Open the news archive and calendar →</a></p>`;
  } else if (s === "trading-research-bot") {
    extra = `<h3>Rule ideas</h3><div class="tablewrap"><table><tr><th>Rule</th><th>Status</th></tr>${(R?.queue || []).map(q => `<tr><td>${esc(q.title)}</td><td>${esc(q.status)}</td></tr>`).join("")}</table></div>${runsTable(runBots[s])}`;
  } else if (s === "grok-bot") {
    extra = `<h3>Weekly improvement cycles</h3>${(R?.weekly || []).map(w => `<div class="card" style="margin-bottom:8px"><h4>${esc(w.title)}</h4><ul class="clean">${w.headline.map(h => `<li>${esc(h)}</li>`).join("")}</ul></div>`).join("") || "<p class='muted'>None yet.</p>"}${runsTable(runBots[s])}`;
  } else if (s === "opportunity-hunter") {
    const opp = B.opportunities.filter(o => o.status !== "rejected");
    extra = `<h3>Top ideas</h3><p class="muted">Income figures are estimates unless quoted from a program page. Research only: nothing signed up for or paid.</p>
    <div class="grid wide">${opp.slice(0, 6).map(o => `<div class="card"><h4>${esc(o.name)}</h4><p><span class="pill ${o.status === "shortlisted" ? "pass" : ""}">${esc(o.status)}</span><span class="pill">score ${o.score}</span><span class="pill">${esc(o.category)}</span></p>
      <p><b>Income:</b> ${esc(o.income)}</p><p><b>First rupee:</b> ${esc(o.first_rupee)} · <b>Hours/wk:</b> ${esc(o.hours)}</p><p><b>Cost:</b> ${esc(o.cost)}</p><p><b>Risk:</b> ${esc(o.risk)}</p>
      <p class="muted">${o.sources.map(u => link(u)).join(" · ")}</p></div>`).join("")}</div>
    <details><summary>All ${B.opportunities.length} ideas (incl. rejected)</summary><div class="tablewrap"><table><tr><th>Score</th><th>Idea</th><th>Status</th><th>Income (est.)</th><th>Reject reason</th></tr>${B.opportunities.map(o => `<tr><td class="n">${o.score ?? ""}</td><td>${esc(o.name)}</td><td>${esc(o.status)}</td><td>${esc(o.income)}</td><td class="muted">${esc(o.reject_reason)}</td></tr>`).join("")}</table></div></details>`;
  }
  det.innerHTML = `<p><a href="#bots">← All bots</a></p>
  <h2>${b.emoji} ${esc(b.name)}</h2><p>${esc(b.role)}</p>
  <div class="grid wide">
   <div class="card"><h4>Schedule (IST)</h4><ul class="clean">${b.schedule.map(x => `<li>${esc(x)}</li>`).join("")}</ul></div>
   <div class="card"><h4>Reads</h4><ul class="clean">${b.inputs.map(x => `<li>${esc(x)}</li>`).join("")}</ul></div>
   <div class="card"><h4>Writes</h4><ul class="clean">${b.outputs.map(x => `<li>${esc(x)}</li>`).join("")}</ul></div>
   <div class="card"><h4>Hands off to</h4><p>${b.hands_to.map(h => `<span class="pill">${esc(h)}</span>`).join("")}</p><h4 style="margin-top:10px">Rules</h4><ul class="clean">${B.rules.map(r => `<li>${esc(r)}</li>`).join("")}</ul></div>
  </div>
  <div class="note"><b>Latest activity:</b> ${esc(b.latest)}</div>
  ${extra}
  <h3>Other bots</h3><p>${others}</p>`;
  if (s === "market-scout") {
    const sc = B.scout;
    const drawHits = () => { const q = $("#hQ").value.toLowerCase(); $("#hits tbody").innerHTML = sc.hits.filter(h => !q || (h.symbol + " " + h.setup + " " + h.scan).toLowerCase().includes(q)).map(h => `<tr><td>${esc(h.time)}</td><td>${esc(h.scan)}</td><td><b>${esc(h.symbol)}</b></td><td>${esc(h.setup)}</td><td class="n">${h.price ?? ""}</td><td class="n">${h.over_pct ?? ""}</td><td>${esc(h.news)} ${h.news_url ? link(h.news_url) : ""}</td></tr>`).join(""); };
    $("#hQ").addEventListener("input", drawHits); drawHits();
    const se = Object.entries(sc.by_setup);
    chart("setupChart", { type: "doughnut", data: { labels: se.map(x => x[0]), datasets: [{ data: se.map(x => x[1]) }] }, options: { maintainAspectRatio: false, plugins: { legend: { position: "right" }, title: { display: true, text: "Hits by setup" } } } });
  }
  window.scrollTo(0, 0);
}
let mermaidDone = false;
function renderMermaid() { if (mermaidDone || !window.mermaid) return; mermaidDone = true; mermaid.initialize({ startOnLoad: false, theme: "default" }); mermaid.run({ nodes: [document.getElementById("flow")] }); }

load();
